    #[test]
    fn single_group_rules_all_apply() {
        let rules = vec![
            Rule::new(
                "web",
                "staff",
                Action::Allow,
                Matcher::new(
                    Protocol::Tcp,
                    None,
                    Some(PortRange::single(443)),
                ),
            ),
            Rule::new(
                "dns",
                "staff",
                Action::Allow,
                Matcher::new(Protocol::Udp, None, Some(PortRange::single(53))),
            ),
        ];

        let policy = resolve(
            &groups(),
