        );
        assert_eq!(
            policy.verdict(&Flow::udp(ip("1.1.1.1"), 53)),
            Action::Allow
        );
        assert_eq!(
            policy.verdict(&Flow::tcp(ip("1.1.1.1"), 22)),
            Action::Deny
        );
    }

    #[test]
    fn different_priorities_override_instead_of_conflict() {
        let rules = vec![
            Rule::new(
                "allow-web",
                "staff",
                Action::Allow,
                Matcher::new(Protocol::Tcp, None, Some(PortRange::single(443))),
            ),
            Rule::new(
                "deny-web",
                "restricted",
                Action::Deny,
                Matcher::new(Protocol::Tcp, None, Some(PortRange::single(443))),
            ),
        ];

        let policy = resolve(
            &groups(),
            &rules,
            &["staff".to_owned(), "restricted".to_owned()],
            Action::Deny,
        )
        .unwrap();

        assert_eq!(policy.effective[0].rule_id, "deny-web");
        assert_eq!(policy.effective[0].priority, 100);
        assert_eq!(policy.verdict(&Flow::tcp(ip("8.8.8.8"), 443)), Action::Deny);
        assert!(policy.effective[0].shadows.contains(&"allow-web".to_owned()));
    }

